import random
from collections import defaultdict

def check_girth(adj, n, max_cycle=6):
    """Check if graph has any cycle of length <= max_cycle"""
    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS
        dist = {start: 0}
        parent = {start: None}
        queue = [start]
        idx = 0
        while idx < len(queue):
            u = queue[idx]
            idx += 1
            if dist[u] >= max_cycle:
                continue
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent.get(u) and dist[v] >= dist[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_cycle:
                        return False, cycle_len
    return True, None

def generate_3colorable_graph(n, target_edges, max_attempts=10000):
    """Generate a 3-colorable graph by first assigning colors, then adding edges"""
    for attempt in range(max_attempts):
        # Random 3-coloring
        coloring = [random.randint(0, 2) for _ in range(n)]

        # Possible edges are between different colors
        possible_edges = []
        for i in range(n):
            for j in range(i+1, n):
                if coloring[i] != coloring[j]:
                    possible_edges.append((i, j))

        random.shuffle(possible_edges)

        # Greedily add edges while maintaining girth >= 7
        adj = defaultdict(set)
        edges = []

        for u, v in possible_edges:
            if len(edges) >= target_edges:
                break

            # Check if adding (u,v) creates a short cycle
            # Temporarily add edge and check
            adj[u].add(v)
            adj[v].add(u)

            # Check for cycles involving this edge
            # BFS from u to v (without using edge u-v)
            found_short_cycle = False
            queue = [(u, 0, None)]  # (node, dist, parent)
            visited = {u: 0}

            while queue:
                node, d, par = queue.pop(0)
                if d >= 6:
                    continue
                for neighbor in adj[node]:
                    if neighbor == par:
                        continue
                    if neighbor == v:
                        cycle_len = d + 2  # d edges from u to node, 1 edge node-v, 1 edge v-u
                        if cycle_len <= 6:
                            found_short_cycle = True
                            break
                    if neighbor not in visited:
                        visited[neighbor] = d + 1
                        queue.append((neighbor, d + 1, node))

            if found_short_cycle:
                adj[u].remove(v)
                adj[v].remove(u)
            else:
                edges.append((u, v))

        if len(edges) >= target_edges:
            # Verify girth
            full_adj = defaultdict(set)
            for u, v in edges:
                full_adj[u].add(v)
                full_adj[v].add(u)

            ok, cycle_len = check_girth(full_adj, n)
            if ok:
                return edges, coloring

    return None, None

