import random
from collections import defaultdict

def find_graph(n, target_edges, girth_min=7):
    """Use backtracking to find a graph with given properties"""

    # First, let's try to build a 3-colorable graph
    # by partitioning vertices into 3 color classes

    best_edges = []

    # Try different partition sizes
    for partition in generate_partitions(n, 3):
        edges = try_build_graph(n, partition, target_edges, girth_min)
        if edges and len(edges) >= target_edges:
            return edges

    return None

def generate_partitions(n, k):
    """Generate partitions of n vertices into k color classes"""
    # We'll generate random partitions
    partitions = []
    for _ in range(1000):
        p = [random.randint(0, k-1) for _ in range(n)]
        # Ensure each class has at least 1 vertex
        if len(set(p)) == k:
            partitions.append(p)
    return partitions

def try_build_graph(n, coloring, target_edges, girth_min):
    """Try to build a graph with given coloring and girth constraint"""
    adj = defaultdict(set)
    edges = []

    # Get all possible edges (between different colors)
    possible = []
    for i in range(n):
        for j in range(i+1, n):
            if coloring[i] != coloring[j]:
                possible.append((i, j))

    random.shuffle(possible)

    for u, v in possible:
        if len(edges) >= target_edges:
            break

        # Check if adding (u,v) creates a cycle of length < girth_min
        if not creates_short_cycle(adj, u, v, girth_min):
            adj[u].add(v)
            adj[v].add(u)
            edges.append((u, v))

    return edges if len(edges) >= target_edges else None

def creates_short_cycle(adj, u, v, girth_min):
    """Check if adding edge (u,v) creates a cycle of length < girth_min"""
    # BFS from u to find shortest path to v
    queue = [(u, 0)]
    visited = {u: 0}

    while queue:
        node, dist = queue.pop(0)
        if dist >= girth_min - 1:
            continue
        for neighbor in adj[node]:
            if neighbor == v:
                cycle_len = dist + 2
                if cycle_len < girth_min:
                    return True
            if neighbor not in visited:
                visited[neighbor] = dist + 1
                queue.append((neighbor, dist + 1))

    return False

